import styles from "./reading-motion.module.css"
import { cn } from "./utils"

/** Decorative cursor; never hides or replaces the reader's real pointer. */
export function ReadingCursor({ show = true }: { show?: boolean }) {
  return (
    <span data-motion-cursor aria-hidden="true" className={cn(styles.cursor, !show && styles.hiddenCursor)}>
      <svg viewBox="0 0 24 24" fill="none">
        <path d="M4.4 3.1C3.2 3.3 2.6 4.5 3.1 5.9L7.8 19.3C8.5 21.4 10.4 22 11.5 19.9L14.1 14.8L19.3 12.2C21.4 11.1 20.8 9.2 18.7 8.5L5.3 3.7C4.9 3.6 4.6 3.5 4.4 3.1Z" fill="black" stroke="white" strokeWidth="2" strokeLinejoin="round" />
      </svg>
    </span>
  )
}

export interface LineRect { x: number; y: number; width: number; height: number }
export const clamp = (value: number, min = 0, max = 1) => Math.min(max, Math.max(min, Number.isFinite(value) ? value : min))
const smoothstep = (value: number) => value * value * (3 - 2 * value)

/** Range rectangles from nested rich text, coalesced into visual lines. */
export function mergeLineRects(rects: readonly LineRect[]): LineRect[] {
  const lines: LineRect[] = []
  for (const rect of rects.filter(r => r.width > 0 && r.height > 0).toSorted((a, b) => a.y - b.y || a.x - b.x)) {
    const previous = lines.at(-1)
    if (previous && Math.abs(previous.y - rect.y) < Math.min(previous.height, rect.height) * 0.5) {
      const right = Math.max(previous.x + previous.width, rect.x + rect.width)
      const bottom = Math.max(previous.y + previous.height, rect.y + rect.height)
      previous.x = Math.min(previous.x, rect.x)
      previous.y = Math.min(previous.y, rect.y)
      previous.width = right - previous.x
      previous.height = bottom - previous.y
    } else lines.push({ ...rect })
  }
  return lines
}

export function measureLines(text: HTMLElement, origin: DOMRect): LineRect[] {
  const walker = document.createTreeWalker(text, NodeFilter.SHOW_TEXT)
  const rects: LineRect[] = []
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    const range = document.createRange()
    range.selectNodeContents(node)
    for (const r of range.getClientRects()) rects.push({ x: r.left - origin.left, y: r.top - origin.top, width: r.width, height: r.height })
  }
  return mergeLineRects(rects)
}

/** Entry at the bottom of the root through arrival at its midpoint. */
export function scrollProgress(top: number, height: number, rootTop: number, rootHeight: number): number {
  return clamp((rootTop + rootHeight - top) / Math.max(1, (height + rootHeight) / 2))
}

function contactOffset(progress: number, start: number, end: number, rtl: boolean) {
  const sign = rtl ? -1 : 1
  const entering = progress < start
  const remaining = entering ? 1 - clamp(progress / start) : clamp((progress - end) / (1 - end))
  const x = entering ? -36 * sign : 64 * sign
  const y = entering ? 48 : -40
  const bow = entering ? 18 * sign : 20 * sign
  const length = Math.hypot(x, y)
  const t = 1 - remaining
  return { x: remaining * x - 2 * remaining * t * y / length * bow, y: remaining * y + 2 * remaining * t * x / length * bow }
}

export function highlightFrame(lines: readonly LineRect[], progress: number, rtl = false) {
  const p = clamp(progress)
  const total = lines.reduce((sum, line) => sum + line.width, 0) + 24 * Math.max(0, lines.length - 1)
  let distance = clamp((p - 0.2) / 0.6) * total
  let x = 0, y = 0, lineOpacity = 1
  const fills = lines.map((line, index) => {
    const fill = clamp(distance, 0, line.width)
    if (distance >= 0) {
      x = line.x + (rtl ? line.width - fill : fill)
      y = line.y + line.height * 0.65
      const edge = Math.min(60, line.width * 0.45)
      lineOpacity = smoothstep(Math.min(index > 0 ? clamp(fill / edge) : 1, index < lines.length - 1 ? clamp((line.width - fill) / edge) : 1))
    }
    distance -= line.width
    const next = lines[index + 1]
    if (next && distance >= 0 && distance <= 24) {
      lineOpacity = 0
      if (distance >= 12) { x = next.x + (rtl ? next.width : 0); y = next.y + next.height * 0.65 }
    }
    distance -= 24
    return fill / line.width
  })
  const offset = contactOffset(p, 0.2, 0.8, rtl)
  const contact = smoothstep(clamp(Math.min(clamp((p - 0.2) / 0.6), 1 - clamp((p - 0.2) / 0.6)) / 0.1))
  return { fills, x: x + offset.x, y: y + offset.y, rotation: p >= 0.2 && p <= 0.8 ? (rtl ? 90 : 0) : (p < 0.2 ? 51 : 75), scale: 1 - 0.14 * contact, opacity: lines.length ? lineOpacity * Math.min(clamp(p / 0.08), clamp((1 - p) / 0.12)) : 0 }
}

export function paragraphFrame(progress: number, offset: { x: number; y: number }, rotation: number, rtl = false) {
  const p = clamp(progress)
  const t = clamp((p - 0.12) / 0.66)
  const remaining = 1 - t
  const length = Math.hypot(offset.x, offset.y) || 1
  const bow = 32 * (rtl ? -1 : 1)
  return {
    x: remaining * offset.x - 2 * remaining * t * offset.y / length * bow,
    y: remaining * offset.y + 2 * remaining * t * offset.x / length * bow,
    rotation: remaining * rotation,
    opacity: Math.min(clamp(p / 0.08), clamp((1 - p) / 0.12)),
    scale: 1 - 0.14 * smoothstep(clamp(Math.min(t, 1 - t) / 0.1)),
  }
}

"use client"

import { useCallback } from "react"
import { useReadingMotion } from "./use-reading-motion"
import { createParagraphPainter } from "./painters"
import { ReadingCursor } from "./cursor"
import type { MotionParagraphProps } from "./types"
import styles from "./reading-motion.module.css"
import { cn } from "./utils"

export function MotionParagraph({ children, className, as: Tag = "div", offset, rotation = 5, trigger, active, playKey, duration, delay, once, showCursor = true, scrollRoot, autoScroll, onComplete, onProgress, ref, ...props }: MotionParagraphProps) {
  const x = offset?.x, y = offset?.y
  const createPainter = useCallback((root: HTMLElement) => createParagraphPainter(root, x !== undefined && y !== undefined ? { x, y } : undefined, rotation), [x, y, rotation])
  const root = useReadingMotion({ trigger, active, playKey, duration, delay, once, scrollRoot, autoScroll, onComplete, onProgress, ref }, createPainter)
  const TextTag = Tag === "span" ? "span" : "div"
  return (
    <Tag {...props} ref={root as React.RefObject<HTMLDivElement>} className={cn(styles.paragraph, Tag === "span" && styles.inline, className)} data-reading-motion="paragraph" data-state="idle">
      <TextTag className={styles.paragraphText} data-motion-text>{children}</TextTag>
      <ReadingCursor show={showCursor} />
    </Tag>
  )
}

import { highlightFrame, measureLines, paragraphFrame, type LineRect } from "./geometry"
import type { MotionPainter } from "./use-reading-motion"
import styles from "./reading-motion.module.css"

function elements(root: HTMLElement) {
  const text = root.querySelector<HTMLElement>("[data-motion-text]")!
  const cursor = root.querySelector<HTMLElement>("[data-motion-cursor]")!
  const glyph = cursor.querySelector("svg")!
  return { text, cursor, glyph }
}

function cursorPose(cursor: HTMLElement, glyph: SVGElement, x: number, y: number, rotation: number, scale: number, opacity: number) {
  cursor.style.transform = `translate3d(${x - 4}px,${y - 4}px,0)`
  cursor.style.opacity = String(opacity)
  glyph.style.transform = `rotate(${rotation}deg) scale(${scale})`
}

export function createHighlightPainter(root: HTMLElement): MotionPainter {
  const { text, cursor, glyph } = elements(root)
  const overlay = root.querySelector<HTMLElement>("[data-motion-overlay]")!
  let lines: LineRect[] = []
  let fills: HTMLElement[] = []
  let rtl = false
  let savedProgress = 0, savedReduced = false, enabled = false
  const draw = (progress: number, reduced: boolean) => {
    enabled = true; savedProgress = progress; savedReduced = reduced
    const result = highlightFrame(lines, progress, rtl)
    fills.forEach((line, i) => { line.style.transform = `scaleX(${result.fills[i]})` })
    cursorPose(cursor, glyph, result.x, result.y, result.rotation, result.scale, reduced ? 0 : result.opacity)
  }
  return {
    measure() {
      rtl = getComputedStyle(root).direction === "rtl"
      lines = measureLines(text, overlay.getBoundingClientRect())
      fills = lines.map(line => {
        const element = document.createElement("span")
        element.className = styles.line
        element.dataset.motionLine = ""
        Object.assign(element.style, { left: `${line.x}px`, top: `${line.y}px`, width: `${line.width}px`, height: `${line.height}px`, transformOrigin: rtl ? "right center" : "left center" })
        return element
      })
      overlay.replaceChildren(...fills)
      if (enabled) draw(savedProgress, savedReduced)
    },
    draw,
    clear() { enabled = false; cursor.style.opacity = "0"; fills.forEach(line => { line.style.transform = "scaleX(0)" }) },
  }
}

export function createParagraphPainter(root: HTMLElement, customOffset?: { x: number; y: number }, customRotation = 5): MotionPainter {
  const { text, cursor, glyph } = elements(root)
  let offset = { x: 110, y: 24 }, width = 0, height = 0, rtl = false
  let savedProgress = 0, savedReduced = false, enabled = false
  const draw = (progress: number, reduced: boolean) => {
    enabled = true; savedProgress = progress; savedReduced = reduced
    const result = paragraphFrame(reduced ? 1 : progress, offset, customRotation * (rtl ? -1 : 1), rtl)
    text.style.transform = result.x === 0 && result.y === 0 && result.rotation === 0 ? "" : `translate3d(${result.x}px,${result.y}px,0) rotate(${result.rotation}deg)`
    const angle = result.rotation * Math.PI / 180
    const anchorX = width * ((rtl ? 0.2 : 0.8) - 0.5), anchorY = height * -0.1
    cursorPose(cursor, glyph, result.x + width / 2 + anchorX * Math.cos(angle) - anchorY * Math.sin(angle), result.y + height / 2 + anchorX * Math.sin(angle) + anchorY * Math.cos(angle), progress < 0.12 ? 75 : 135, result.scale, reduced ? 0 : result.opacity)
  }
  return {
    measure() {
      rtl = getComputedStyle(root).direction === "rtl"
      width = text.offsetWidth; height = text.offsetHeight
      offset = { x: (customOffset?.x ?? Math.min(110, window.innerWidth * 0.18)) * (rtl ? -1 : 1), y: customOffset?.y ?? 24 }
      if (enabled) draw(savedProgress, savedReduced)
    },
    draw,
    clear() { enabled = false; text.style.transform = ""; cursor.style.opacity = "0" },
  }
}

.highlight { position: relative; isolation: isolate; --reading-motion-highlight: #539af8; }
.highlight[data-color="green"] { --reading-motion-highlight: #65bd92; }
.highlight[data-color="orange"] { --reading-motion-highlight: #f4ae67; }
.text { position: relative; z-index: 1; }
.overlay { position: absolute; top: 0; left: 0; pointer-events: none; }
.line { position: absolute; border-radius: .14em; background: var(--reading-motion-highlight); opacity: .45; transform: scaleX(0); transform-origin: left center; }
.cursor { position: absolute; top: 0; left: 0; z-index: 2; width: 24px; height: 24px; opacity: 0; pointer-events: none; user-select: none; }
.cursor svg { display: block; width: 100%; height: 100%; transform-origin: 4px 4px; }
.hiddenCursor { display: none; }
.paragraph { position: relative; isolation: isolate; display: block; max-width: 100%; }
.inline { display: inline-block; vertical-align: baseline; }
.paragraphText { position: relative; z-index: 1; display: block; max-width: 100%; overflow-wrap: anywhere; }
.inline .paragraphText { display: inline-block; }
@media (prefers-reduced-motion: reduce) {
  .cursor { display: none; }
  .paragraphText { transform: none !important; }
}

/** One event hub and animation frame for all mounted reading effects. */
export interface MotionSubscriber {
  measure: () => void
  paint: (time: number, reduced: boolean) => boolean
}

const subscribers = new Set<MotionSubscriber>()
let frame = 0
let dirty = true
let cleanup: (() => void) | undefined
let reducedQuery: MediaQueryList | undefined

export function requestMotionFrame(remeasure = false) {
  dirty ||= remeasure
  if (!frame && subscribers.size && document.visibilityState !== "hidden") frame = requestAnimationFrame(tick)
}

function tick(time: number) {
  frame = 0
  if (document.visibilityState === "hidden") return
  if (dirty) { dirty = false; subscribers.forEach(entry => entry.measure()) }
  let keepAlive = false
  subscribers.forEach(entry => { keepAlive = entry.paint(time, reducedQuery?.matches ?? false) || keepAlive })
  if (keepAlive) requestMotionFrame()
}

export function subscribeMotion(entry: MotionSubscriber) {
  subscribers.add(entry)
  if (!cleanup) {
    reducedQuery = matchMedia("(prefers-reduced-motion: reduce)")
    const update = () => requestMotionFrame()
    const resize = () => requestMotionFrame(true)
    const visibility = () => {
      if (document.visibilityState === "hidden") { cancelAnimationFrame(frame); frame = 0 }
      else resize()
    }
    // Capture includes nested scroll containers, even when events do not bubble.
    document.addEventListener("scroll", update, { capture: true, passive: true })
    window.addEventListener("resize", resize, { passive: true })
    window.addEventListener("pageshow", resize)
    document.addEventListener("visibilitychange", visibility)
    reducedQuery.addEventListener("change", update)
    let disposed = false
    document.fonts?.ready.then(() => { if (!disposed) resize() })
    document.fonts?.addEventListener("loadingdone", resize)
    cleanup = () => {
      disposed = true
      document.removeEventListener("scroll", update, true)
      window.removeEventListener("resize", resize)
      window.removeEventListener("pageshow", resize)
      document.removeEventListener("visibilitychange", visibility)
      reducedQuery?.removeEventListener("change", update)
      document.fonts?.removeEventListener("loadingdone", resize)
      reducedQuery = undefined
    }
  }
  requestMotionFrame(true)
  return () => {
    subscribers.delete(entry)
    if (!subscribers.size) { cleanup?.(); cleanup = undefined; cancelAnimationFrame(frame); frame = 0; dirty = true }
  }
}

import type { ComponentPropsWithoutRef, Ref } from "react"

export interface ReadingMotionHandle {
  /** Play when visible; optionally scroll the target into view first. */
  play: (options?: { scrollIntoView?: boolean }) => void
  reset: () => void
  finish: () => void
  scrollIntoView: () => void
}

export interface ReadingMotionOptions {
  trigger?: "scroll" | "visible" | "manual"
  active?: boolean
  /** Change to replay, including when active already is true. */
  playKey?: string | number
  duration?: number
  delay?: number
  once?: boolean
  showCursor?: boolean
  /** Optional independently scrolling viewport. */
  scrollRoot?: HTMLElement | null
  /** Scroll into view on manual playback; motion starts on arrival. */
  autoScroll?: boolean
  onComplete?: () => void
  onProgress?: (progress: number) => void
  ref?: Ref<ReadingMotionHandle>
}

export interface CursorHighlightProps extends Omit<ComponentPropsWithoutRef<"span">, "onProgress">, ReadingMotionOptions {
  color?: "blue" | "green" | "orange"
}

export interface MotionParagraphProps extends Omit<ComponentPropsWithoutRef<"div">, "onProgress">, ReadingMotionOptions {
  as?: "div" | "span"
  offset?: { x: number; y: number }
  rotation?: number
}

"use client"

import { useEffect, useImperativeHandle, useLayoutEffect, useRef } from "react"
import type { ReadingMotionHandle, ReadingMotionOptions } from "./types"
import { clamp, scrollProgress } from "./geometry"
import { requestMotionFrame, subscribeMotion } from "./runtime"

export interface MotionPainter { measure: () => void; draw: (progress: number, reduced: boolean) => void; clear: () => void }

export function useReadingMotion(options: ReadingMotionOptions, createPainter: (root: HTMLElement) => MotionPainter) {
  const { trigger = "scroll", active = true, playKey, duration = 1800, delay = 0, once = true, scrollRoot, autoScroll = false, ref } = options
  const rootRef = useRef<HTMLElement>(null)
  const commands = useRef<ReadingMotionHandle | null>(null)
  const callbacks = useRef({ onComplete: options.onComplete, onProgress: options.onProgress })
  useEffect(() => { callbacks.current = { onComplete: options.onComplete, onProgress: options.onProgress } }, [options.onComplete, options.onProgress])
  useImperativeHandle(ref, () => ({
    play: settings => commands.current?.play(settings),
    reset: () => commands.current?.reset(),
    finish: () => commands.current?.finish(),
    scrollIntoView: () => commands.current?.scrollIntoView(),
  }), [])

  useLayoutEffect(() => {
    const root = rootRef.current
    if (!root) return
    const painter = createPainter(root)
    let started: number | null = null
    let pending = active && trigger !== "scroll"
    let finished = false
    let paused = !active
    let current = 0
    let last = -1
    let lastReduced = false
    let lastTime = 0
    let focused = false
    let explicitPlayback = trigger === "manual"
    let awaitingScroll = false
    let lastScrollTop = 0
    let stableSince = 0
    let requestedAt = 0
    const scroll = () => root.scrollIntoView({ block: "center", behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth" })
    const scrollBeforePlayback = () => {
      awaitingScroll = true
      lastScrollTop = root.getBoundingClientRect().top
      stableSince = requestedAt = performance.now()
      scroll()
    }
    const complete = () => { if (!finished) { finished = true; callbacks.current.onComplete?.() } }
    const paint = (time: number, reduced: boolean) => {
      if (paused) return false
      const rect = root.getBoundingClientRect()
      const bounds = scrollRoot?.getBoundingClientRect()
      const rootTop = bounds ? bounds.top + scrollRoot!.clientTop : 0
      const rootHeight = scrollRoot?.clientHeight ?? window.innerHeight
      const visible = explicitPlayback
        ? rect.bottom > rootTop && rect.top < rootTop + rootHeight
        : rect.bottom > rootTop + rootHeight * 0.15 && rect.top < rootTop + rootHeight * 0.85
      if (awaitingScroll) {
        if (Math.abs(rect.top - lastScrollTop) > 0.5) stableSince = time
        lastScrollTop = rect.top
        // A stable-position fallback also covers browsers without scrollend,
        // interrupted smooth scrolls, and targets already in the center.
        if (reduced || focused || time - stableSince >= 120 || time - requestedAt >= 2500) awaitingScroll = false
      }
      if (trigger === "scroll" && !pending && started === null) {
        const target = scrollProgress(rect.top, rect.height, rootTop, rootHeight)
        const dt = lastTime ? Math.min(64, time - lastTime) : 64
        current = reduced || focused || !lastTime ? target : current + (target - current) * (1 - Math.exp(-dt / 55))
        if (Math.abs(target - current) < 0.0005) current = target
      } else {
        if (pending && visible && !awaitingScroll) { pending = false; started = time + (Number.isFinite(delay) ? Math.max(0, delay) : 0); finished = false }
        if (started !== null) current = reduced || focused ? 1 : clamp((time - started) / (Number.isFinite(duration) ? Math.max(1, duration) : 1800))
        if (current === 1 && !once && trigger === "visible" && !visible) { current = 0; started = null; pending = true; finished = false }
      }
      if (reduced || focused) current = trigger === "scroll" || !pending || finished ? 1 : current
      if (current !== last || (reduced || focused) !== lastReduced) {
        painter.draw(current, reduced || focused)
        root.dataset.state = current === 1 ? "complete" : current === 0 ? "idle" : "playing"
        callbacks.current.onProgress?.(current)
        last = current; lastReduced = reduced || focused
      }
      if (current === 1) complete()
      else if (trigger === "scroll") finished = false
      lastTime = time
      const target = scrollProgress(rect.top, rect.height, rootTop, rootHeight)
      return awaitingScroll || (!reduced && !focused && ((started !== null && current < 1) || (trigger === "scroll" && !pending && started === null && Math.abs(target - current) > 0.0005)))
    }
    commands.current = {
      play(settings) {
        paused = false; pending = true; started = null; current = 0; finished = false; last = -1; awaitingScroll = false; explicitPlayback = true
        painter.clear(); root.dataset.state = "idle"
        if (settings?.scrollIntoView ?? autoScroll) scrollBeforePlayback()
        requestMotionFrame(true)
      },
      reset() { paused = true; pending = false; awaitingScroll = false; started = null; current = 0; last = -1; finished = false; painter.clear(); root.dataset.state = "idle"; callbacks.current.onProgress?.(0) },
      finish() { paused = true; pending = false; awaitingScroll = false; started = null; current = 1; painter.measure(); painter.draw(1, true); root.dataset.state = "complete"; callbacks.current.onProgress?.(1); complete() },
      scrollIntoView: scroll,
    }
    const focusIn = () => { focused = true; requestMotionFrame() }
    const focusOut = () => { focused = false; requestMotionFrame() }
    root.addEventListener("focusin", focusIn)
    root.addEventListener("focusout", focusOut)
    const observer = new ResizeObserver(() => requestMotionFrame(true))
    observer.observe(root)
    if (root.parentElement) observer.observe(root.parentElement)
    if (scrollRoot) observer.observe(scrollRoot)
    const mutation = new MutationObserver(() => requestMotionFrame(true))
    const text = root.querySelector("[data-motion-text]")
    if (text) mutation.observe(text, { childList: true, characterData: true, subtree: true })
    const unsubscribe = subscribeMotion({ measure: painter.measure, paint })
    if (pending && autoScroll && trigger === "manual") scrollBeforePlayback()
    if (!active) { painter.clear(); root.dataset.state = "idle" }
    return () => {
      unsubscribe(); observer.disconnect(); mutation.disconnect(); commands.current = null
      root.removeEventListener("focusin", focusIn); root.removeEventListener("focusout", focusOut)
      painter.clear()
    }
  }, [active, autoScroll, createPainter, delay, duration, once, playKey, scrollRoot, trigger])
  return rootRef
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
